const M = {};
M.config = (function () {
  const module = { exports: {} };
/**
 * config.js – builds the runtime config for every workflow from environment variables.
 * Used by the first "Config" Code node in each workflow. Secrets are NOT copied into
 * the output (execution data is stored in n8n); HTTP nodes read tokens from $env directly.
 */
function bool(v, dflt) {
  if (v === undefined || v === null || v === '') return dflt;
  return String(v).trim().toLowerCase() === 'true';
}

function parseList(v) {
  return String(v || '')
    .split(/[,;\s]+/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

function parseLimit(v, demoMode) {
  if (v === undefined || v === null || v === '') return demoMode ? 10 : null;
  if (String(v).trim().toLowerCase() === 'off') return null;
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : 10;
}

function trimSlash(u) {
  return String(u || '').replace(/\/+$/, '');
}

function buildConfig(env) {
  env = env || {};
  // Safe defaults: demo mode ON unless explicitly "false".
  const demoMode = bool(env.DEMO_MODE, true);
  const mock = bool(env.MOCK_EXTERNAL, false);
  const mockBase = trimSlash(env.MOCK_BASE_URL || 'http://host.docker.internal:8787');
  const real = {
    airtable: 'https://api.airtable.com/v0',
    googlePlaces: 'https://places.googleapis.com/v1',
    openai: 'https://api.openai.com/v1',
    anthropic: 'https://api.anthropic.com/v1',
    slack: 'https://slack.com/api',
    gmail: 'https://gmail.googleapis.com/gmail/v1',
    hubspot: 'https://api.hubapi.com',
    dns: 'https://dns.google',
    web: '',
    calendly: 'https://api.calendly.com',
  };
  const mocked = {
    airtable: mockBase + '/airtable/v0',
    googlePlaces: mockBase + '/google/v1',
    openai: mockBase + '/ai/openai/v1',
    anthropic: mockBase + '/ai/anthropic/v1',
    slack: mockBase + '/slack/api',
    gmail: mockBase + '/gmail/v1',
    hubspot: mockBase + '/hubspot',
    dns: mockBase + '/dns',
    web: mockBase + '/web',
    calendly: mockBase + '/calendly',
  };
  const urls = mock ? mocked : real;
  const aiProvider = String(env.AI_PROVIDER || 'openai').toLowerCase() === 'anthropic' ? 'anthropic' : 'openai';
  const allowlist = parseList(env.TEST_RECIPIENT_ALLOWLIST);
  const conf = parseFloat(env.AUTO_REPLY_MIN_CONFIDENCE);
  return {
    demoMode,
    mock,
    allowRealSending: !demoMode && bool(env.ALLOW_REAL_SENDING, false),
    // DEMO_MODE sends from an every-minute ticker; the test stack turns it off and drives sends by webhook
    demoTicker: !bool(env.DISABLE_DEMO_TICKER, false),
    // cap per run so one run always finishes before the next tick (no overlapping runs)
    // demo: 10 per minute tick with 1 s gaps (~45 s per run, so runs never overlap); real: 5 per 15-min tick, 60–180 s apart
    maxSendsPerRun: demoMode ? 10 : 5,
    testLeadLimit: parseLimit(env.TEST_LEAD_LIMIT, demoMode),
    allowlist,
    testProspectEmail: String(env.TEST_PROSPECT_EMAIL || '').trim().toLowerCase(),
    senderEmail: String(env.SENDER_EMAIL || '').trim().toLowerCase(),
    autoReplyMinConfidence: Number.isFinite(conf) ? conf : 0.85,
    unsureConfidence: 0.7,
    timezone: 'Europe/Berlin',
    airtableBaseId: env.AIRTABLE_BASE_ID || '',
    airtableUrl: urls.airtable + '/' + (env.AIRTABLE_BASE_ID || ''),
    googlePlacesUrl: urls.googlePlaces,
    aiProvider,
    aiModel: env.AI_MODEL || (aiProvider === 'anthropic' ? 'claude-haiku-5-5' : 'gpt-4o-mini'),
    aiUrl: aiProvider === 'anthropic' ? urls.anthropic + '/messages' : urls.openai + '/chat/completions',
    slackApiUrl: urls.slack,
    slackChannel: env.SLACK_CHANNEL || '#leads',
    gmailUrl: urls.gmail,
    hubspotUrl: urls.hubspot,
    dnsUrl: urls.dns,
    webProxyUrl: urls.web,
    calendlyLink: env.CALENDLY_LINK || '',
    calendlyApiUrl: urls.calendly,
    n8nBaseUrl: trimSlash(env.WEBHOOK_URL || 'http://localhost:5678'),
    n8nInternalUrl: trimSlash(env.N8N_INTERNAL_URL || 'http://localhost:5678'),
    interfaceUrl: env.AIRTABLE_INTERFACE_URL || (env.AIRTABLE_BASE_ID ? 'https://airtable.com/' + env.AIRTABLE_BASE_ID : ''),
    googleCostPerRequestEur: 0.032,
  };
}

/** URL to fetch a company web page; in mock mode served by the mock server. */
function webUrl(cfg, domain, path) {
  path = path || '/';
  if (cfg.webProxyUrl) return cfg.webProxyUrl + '/' + domain + path;
  return 'https://' + domain + path;
}

const configApi = { buildConfig, webUrl, parseList, parseLimit };
if (typeof module !== 'undefined' && module.exports) module.exports = configApi;

  return module.exports;
})();

// ---- node logic ----
const trigger = $input.all().map((i) => i.json);
// test stack only: schedules are switched off so tests drive every module through its webhook
const scheduled = trigger.length > 0 && trigger[0] && trigger[0]['Readable date'] !== undefined;
if (scheduled && String($env.DISABLE_SCHEDULES).toLowerCase() === 'true') return [];
return [{ json: { cfg: M.config.buildConfig($env), trigger, startedAt: new Date().toISOString() } }];

const list = ($json.collection || []);
if ($json.error || $json.message && !$json.collection) throw new Error('Calendly API error: ' + ($json.message || JSON.stringify($json.error)));
return list.map((e) => ({ json: { event: e, uuid: String(e.uri).split('/').pop() } }));

const M = {};
M.calendly = (function () {
  const module = { exports: {} };
/**
 * calendly.js – Module 7b: parse Calendly webhook payloads (invitee.created / invitee.canceled).
 * Idempotent: the same event URI twice produces one meeting.
 */
function parseCalendly(body) {
  const b = (body && (body.body || body)) || {};
  const p = b.payload || {};
  const event = b.event || '';
  const scheduled = p.scheduled_event || {};
  return {
    event,
    email: String(p.email || '').toLowerCase(),
    name: p.name || '',
    invitee_uri: p.uri || '',
    event_uri: scheduled.uri || p.event || '',
    calendly_event_id: String(scheduled.uri || p.event || p.uri || '').split('/').filter(Boolean).pop() || '',
    start_time: scheduled.start_time || p.start_time || null,
    end_time: scheduled.end_time || null,
    cancel_reason: (p.cancellation && p.cancellation.reason) || '',
    utm_content: (p.tracking && p.tracking.utm_content) || '',
    // answers to the booking form's questions (e.g. object size, contract end) go into the meeting brief
    questions: (Array.isArray(p.questions_and_answers) ? p.questions_and_answers : [])
      .filter((q) => q && q.question && q.answer).map((q) => ({ question: String(q.question), answer: String(q.answer) })),
    valid: (event === 'invitee.created' || event === 'invitee.canceled') && !!p.email,
  };
}

/** decide what to do given existing Meetings with the same calendly_event_id */
function meetingAction(parsed, existingMeetings) {
  const existing = (existingMeetings || []).find((m) => m.calendly_event_id === parsed.calendly_event_id);
  if (parsed.event === 'invitee.created') return existing ? { action: 'skip', reason: 'duplicate webhook', meeting: existing } : { action: 'create' };
  if (parsed.event === 'invitee.canceled') return existing ? (existing.status === 'Cancelled' ? { action: 'skip', reason: 'already cancelled', meeting: existing } : { action: 'cancel', meeting: existing }) : { action: 'skip', reason: 'unknown meeting' };
  return { action: 'skip', reason: 'unsupported event ' + parsed.event };
}

/** Booking link that tells the webhook which lead booked (Calendly passes utm_content back). */
function bookingLink(link, leadRecordId) {
  if (!link) return '';
  return link + (link.includes('?') ? '&' : '?') + 'utm_source=nexsale&utm_content=' + encodeURIComponent(leadRecordId || '');
}

/** Calendly-Webhook-Signature: "t=<ts>,v1=<hmac_sha256(key, t + '.' + body)>" */
function verifyCalendlySignature(opts) {
  const { signingKey, header, rawBody, crypto } = opts || {};
  const now = opts && opts.now !== undefined ? opts.now : Math.floor(Date.now() / 1000);
  if (!signingKey) return { ok: true, skipped: true };
  const parts = Object.fromEntries(String(header || '').split(',').map((kv) => kv.trim().split('=')));
  if (!parts.t || !parts.v1) return { ok: false, reason: 'missing signature' };
  if (Math.abs(now - Number(parts.t)) > 180) return { ok: false, reason: 'signature too old' };
  const expected = crypto.createHmac('sha256', signingKey).update(parts.t + '.' + (rawBody || '')).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(String(parts.v1));
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return { ok: false, reason: 'signature mismatch' };
  return { ok: true };
}

/**
 * Free Calendly plan (no webhooks): turn polled API data into the same payloads a webhook would send,
 * so 07b_calendly handles both the same way. Only invitees created/changed within `windowMinutes` are
 * forwarded; 07b's duplicate check makes overlapping polls harmless.
 * events: GET /scheduled_events collection; inviteesByEvent: { <event uri>: GET /invitees collection }
 */
function pollToPayloads(events, inviteesByEvent, now, windowMinutes) {
  const t = new Date(now || Date.now()).getTime();
  const since = t - (windowMinutes || 30) * 60000;
  const out = [];
  (events || []).forEach((ev) => {
    ((inviteesByEvent || {})[ev.uri] || []).forEach((inv) => {
      const canceled = inv.status === 'canceled' || ev.status === 'canceled';
      const changedAt = new Date(canceled ? inv.updated_at || inv.created_at : inv.created_at).getTime();
      if (!(changedAt >= since)) return;
      out.push({
        event: canceled ? 'invitee.canceled' : 'invitee.created',
        source: 'calendly-poll',
        payload: {
          email: inv.email, name: inv.name, uri: inv.uri, status: inv.status, tracking: inv.tracking || {}, questions_and_answers: inv.questions_and_answers || [],
          cancellation: inv.cancellation || undefined,
          scheduled_event: { uri: ev.uri, name: ev.name, start_time: ev.start_time, end_time: ev.end_time },
        },
      });
    });
  });
  return out;
}

/**
 * Cancel a booked meeting in Calendly (POST /scheduled_events/{uuid}/cancellation; token needs scheduled_events:write).
 * Calendly then sends its own cancellation email to the invitee and removes the event from the host's calendar.
 */
function cancellationRequest(meeting, reason) {
  const uuid = String((meeting && meeting.calendly_event_id) || '').replace(/[^A-Za-z0-9-]/g, '');
  return { meeting_id: meeting && meeting.id, uuid, path: '/scheduled_events/' + (uuid || 'missing') + '/cancellation',
    body: { reason: String(reason || 'Der Interessent hat den Termin abgesagt.').slice(0, 300) } };
}

/** Calendly answers 201 on success; 403 if already cancelled / in the past or the token lacks permission; 404 unknown. */
function cancellationOk(response) {
  const code = Number(response && (response.statusCode || response.status));
  return code === 201 || code === 200;
}

function cancellationProblem(response) {
  const r = response || {};
  const b = r.body || {};
  return (Number(r.statusCode) || '') + ' ' + String(b.title || b.message || r.error || 'no answer').slice(0, 120);
}

const calendlyApi = { cancellationRequest, cancellationOk, cancellationProblem, parseCalendly, meetingAction, bookingLink, verifyCalendlySignature, pollToPayloads };
if (typeof module !== 'undefined' && module.exports) module.exports = calendlyApi;

  return module.exports;
})();

// ---- node logic ----
const evs = $('Events').all().map((i) => i.json.event);
const inv = {};
$input.all().forEach((it, i) => { inv[evs[i].uri] = it.json.collection || []; });
return M.calendly.pollToPayloads(evs, inv, new Date(), 30).map((p) => ({ json: p }));
